import{_ as i,o as l,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const I=JSON.parse('{"title":"VPS 弹性 IP 使用指南","description":"","frontmatter":{"title":"VPS 弹性 IP 使用指南"},"headers":[],"relativePath":"ops-knowledge-base/vps/elastic-ip-guide.md","filePath":"ops-knowledge-base/vps/elastic-ip-guide.md","lastUpdated":1788259091000}'),t={name:"ops-knowledge-base/vps/elastic-ip-guide.md"};function o(p,a,P,s,n,h){return l(),e("div",null,[...a[0]||(a[0]=[r('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍 VPS 弹性 IP（Elastic IP）的功能说明、适用场景及后台操作方法，帮助客户了解弹性 IP 的绑定、解绑及使用注意事项。</p><p><strong>适用产品：</strong></p><ul><li>VPS（Virtual Private Server）</li></ul><hr><h2 id="一、什么是弹性-ip-elastic-ip" tabindex="-1">一、什么是弹性 IP（Elastic IP） <a class="header-anchor" href="#一、什么是弹性-ip-elastic-ip" aria-label="Permalink to &quot;一、什么是弹性 IP（Elastic IP）&quot;">​</a></h2><p>弹性 IP（Elastic IP，简称 EIP）是一种可独立管理的公网 IP 地址，可根据业务需求绑定或解绑 VPS 实例，实现公网 IP 的灵活管理。</p><p>与实例默认公网 IP 不同，弹性 IP 可以独立于实例进行管理，方便业务迁移或网络调整。</p><p><strong>适用场景：</strong></p><ul><li>为 VPS 增加独立公网 IP。</li><li>更换服务器时重新绑定公网 IP。</li><li>根据业务需求灵活管理公网 IP。</li></ul><hr><h2 id="二、进入弹性-ip-管理页面" tabindex="-1">二、进入弹性 IP 管理页面 <a class="header-anchor" href="#二、进入弹性-ip-管理页面" aria-label="Permalink to &quot;二、进入弹性 IP 管理页面&quot;">​</a></h2><p>登录 Raksmart 客户后台。</p><p>依次进入：</p><p><strong>产品管理 → VPS → 弹性 IP</strong></p><p>进入页面后，可查看当前账户下所有弹性 IP，包括：</p><ul><li>IP 地址</li><li>所属区域</li><li>所属线路</li><li>当前状态（已绑定 / 空闲）</li><li>当前绑定实例（如已绑定）</li></ul><hr><h2 id="三、绑定弹性-ip" tabindex="-1">三、绑定弹性 IP <a class="header-anchor" href="#三、绑定弹性-ip" aria-label="Permalink to &quot;三、绑定弹性 IP&quot;">​</a></h2><p>当弹性 IP 处于空闲状态时，可绑定至指定 VPS。</p><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>登录 Raksmart 客户后台。</li><li>进入 <strong>产品管理 → VPS → 弹性 IP</strong>。</li><li>点击进入需要绑定的弹性 IP。</li><li>点击 <strong>分配</strong>。</li><li>在实例列表中选择需要绑定的 VPS。</li><li>确认绑定。</li></ol><p>绑定完成后，系统会自动重启 VPS，使新的网络配置生效。</p><blockquote><p><strong>说明：</strong></p><p>绑定弹性 IP 会导致服务器自动重启，请提前做好业务安排。</p></blockquote><hr><h2 id="四、解绑弹性-ip" tabindex="-1">四、解绑弹性 IP <a class="header-anchor" href="#四、解绑弹性-ip" aria-label="Permalink to &quot;四、解绑弹性 IP&quot;">​</a></h2><p>如需解除弹性 IP 与当前 VPS 的关联，可执行解绑操作。</p><p>目前支持两种解绑方式：</p><h3 id="方式一-在弹性-ip-页面解绑" tabindex="-1">方式一：在弹性 IP 页面解绑 <a class="header-anchor" href="#方式一-在弹性-ip-页面解绑" aria-label="Permalink to &quot;方式一：在弹性 IP 页面解绑&quot;">​</a></h3><ol><li>进入 <strong>产品管理 → VPS → 弹性 IP</strong>。</li><li>找到已绑定的弹性 IP。</li><li>点击 <strong>空闲</strong>。</li><li>确认操作。</li></ol><p>解绑完成后，弹性 IP 将恢复为空闲状态，可用于后续重新绑定。</p><blockquote><p><strong>说明：</strong></p><p>解绑弹性 IP 同样会导致服务器自动重启，请提前确认业务允许中断。</p></blockquote><hr><h2 id="五、绑定规则" tabindex="-1">五、绑定规则 <a class="header-anchor" href="#五、绑定规则" aria-label="Permalink to &quot;五、绑定规则&quot;">​</a></h2><p>弹性 IP 并非可以绑定任意 VPS，需满足以下条件：</p><ul><li>弹性 IP 与 VPS <strong>必须属于同一地区（Region）</strong>。</li><li>弹性 IP 与 VPS <strong>必须属于同一网络线路</strong>。</li></ul><p>例如：</p><ul><li>美国洛杉矶国际 BGP 的弹性 IP，只能绑定美国洛杉矶国际 BGP 的 VPS。</li><li>日本大陆优化线路的弹性 IP，不能绑定日本国际 BGP 线路的 VPS。</li></ul><p>如果服务器与弹性 IP 不满足上述条件，在绑定页面中将<strong>不会显示该服务器</strong>，因此无法完成绑定。</p><hr><h2 id="六、使用建议" tabindex="-1">六、使用建议 <a class="header-anchor" href="#六、使用建议" aria-label="Permalink to &quot;六、使用建议&quot;">​</a></h2><p>建议在以下场景使用弹性 IP：</p><ul><li>需要灵活管理公网 IP。</li><li>业务迁移至新的 VPS。</li><li>更换服务器后继续使用原有公网 IP。</li><li>统一管理多个公网 IP。</li></ul><p>如无需更换公网 IP，可继续使用实例默认公网 IP。</p><hr><h2 id="七、常见问题" tabindex="-1">七、常见问题 <a class="header-anchor" href="#七、常见问题" aria-label="Permalink to &quot;七、常见问题&quot;">​</a></h2><h3 id="q1-为什么绑定页面看不到我的-vps" tabindex="-1">Q1：为什么绑定页面看不到我的 VPS？ <a class="header-anchor" href="#q1-为什么绑定页面看不到我的-vps" aria-label="Permalink to &quot;Q1：为什么绑定页面看不到我的 VPS？&quot;">​</a></h3><p>通常是因为弹性 IP 与 VPS 不属于同一地区或同一线路。</p><p>请确认：</p><ul><li>地区（Region）是否一致。</li><li>网络线路是否一致。</li></ul><p>仅满足上述条件的 VPS 才会显示在绑定列表中。</p><hr><h3 id="q2-绑定弹性-ip-会影响服务器运行吗" tabindex="-1">Q2：绑定弹性 IP 会影响服务器运行吗？ <a class="header-anchor" href="#q2-绑定弹性-ip-会影响服务器运行吗" aria-label="Permalink to &quot;Q2：绑定弹性 IP 会影响服务器运行吗？&quot;">​</a></h3><p>会。</p><p>绑定完成后，系统会自动重启服务器，使网络配置生效。</p><p>建议提前停止业务或选择业务低峰期进行操作。</p><hr><h3 id="q3-解绑弹性-ip-会重启服务器吗" tabindex="-1">Q3：解绑弹性 IP 会重启服务器吗？ <a class="header-anchor" href="#q3-解绑弹性-ip-会重启服务器吗" aria-label="Permalink to &quot;Q3：解绑弹性 IP 会重启服务器吗？&quot;">​</a></h3><p>会。</p><p>解绑完成后，系统同样会自动重启服务器。</p><hr><h3 id="q4-解绑后弹性-ip-会释放吗" tabindex="-1">Q4：解绑后弹性 IP 会释放吗？ <a class="header-anchor" href="#q4-解绑后弹性-ip-会释放吗" aria-label="Permalink to &quot;Q4：解绑后弹性 IP 会释放吗？&quot;">​</a></h3><p>不会。</p><p>解绑后，弹性 IP 将恢复为空闲状态，仍保留在当前账户下，可继续绑定符合条件的 VPS。</p><hr><h3 id="q5-为什么绑定成功后仍无法访问" tabindex="-1">Q5：为什么绑定成功后仍无法访问？ <a class="header-anchor" href="#q5-为什么绑定成功后仍无法访问" aria-label="Permalink to &quot;Q5：为什么绑定成功后仍无法访问？&quot;">​</a></h3><p>建议检查以下内容：</p><ul><li>VPS 是否已完成重启。</li><li>安全组或系统防火墙是否已放行相关端口。</li><li>SSH（Linux）或 RDP（Windows）服务是否正常运行。</li><li>域名解析是否已更新（如使用域名访问）。</li></ul><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ 弹性 IP 与 VPS 必须属于<strong>同一地区、同一线路</strong>，否则无法绑定。</p><p>⚠️ 如果绑定页面未显示目标 VPS，请优先确认地区及线路是否一致。</p><p>⚠️ 绑定、解绑弹性 IP 均会导致服务器自动重启，请提前做好业务安排。</p><p>⚠️ 解绑后的弹性 IP 不会被释放，而是恢复为空闲状态，可再次绑定至符合条件的 VPS。</p><hr>',75)])])}const u=i(t,[["render",o]]);export{I as __pageData,u as default};
